insert into public.competencia (id, trilha, topico_id, titulo, descricao, criterio, ordem) values
  ('py-comp-int-01', 'python', 'py-int-01', 'Modelar objetos com classes', 'Distingue uma definição de classe das instâncias criadas a partir dela.', 'Cria instâncias independentes e identifica estado e comportamento associados à classe.', 10),
  ('py-comp-int-02', 'python', 'py-int-02', 'Definir estado e ações de objetos', 'Inicializa atributos e cria métodos que operam sobre o próprio objeto.', 'Usa self para acessar estado e mantém inicialização coerente com o uso da classe.', 20),
  ('py-comp-int-03', 'python', 'py-int-03', 'Proteger regras do objeto', 'Mantém invariantes por meio de uma interface que valida alterações.', 'Demonstra uma alteração válida e rejeita uma que quebraria a regra do domínio.', 30),
  ('py-comp-int-04', 'python', 'py-int-04', 'Escolher composição ou herança', 'Reutiliza comportamento sem criar hierarquias artificiais.', 'Justifica uma relação tem-um ou é-um com base no comportamento esperado.', 40),
  ('py-comp-int-05', 'python', 'py-int-05', 'Implementar representações úteis', 'Usa métodos especiais para integrar objetos às convenções de Python.', 'Cria representações compreensíveis e explica quando __str__ ou __repr__ é usado.', 50),
  ('py-comp-int-06', 'python', 'py-int-06', 'Transformar coleções com compreensão', 'Usa list comprehensions para expressar transformações curtas e legíveis.', 'Filtra ou transforma dados sem esconder passos importantes em uma expressão longa.', 60),
  ('py-comp-int-07', 'python', 'py-int-07', 'Produzir valores sob demanda', 'Distingue iteráveis, iteradores e generators e reconhece seu consumo progressivo.', 'Usa yield para produzir valores sem criar antecipadamente uma coleção completa.', 70),
  ('py-comp-int-08', 'python', 'py-int-08', 'Comunicar contratos com tipos e dataclasses', 'Usa type hints e dataclasses para tornar dados e interfaces mais claros.', 'Anota entradas e saídas sem presumir que anotações validam valores automaticamente.', 80),
  ('py-comp-int-09', 'python', 'py-int-09', 'Gerir recursos e padrões de texto', 'Usa context managers para limpeza previsível e regex para padrões delimitados.', 'Fecha recursos mesmo em caso de erro e testa padrões com entradas válidas e inválidas.', 90),
  ('py-comp-int-10', 'python', 'py-int-10', 'Comparar estratégias de busca', 'Reconhece busca linear, busca binária e o custo de ordenar ou indexar dados.', 'Implementa busca correta e explica o trabalho esperado para uma lista pequena e uma grande.', 100),
  ('py-comp-projeto-biblioteca', 'python', 'py-int-10', 'Projetar uma aplicação orientada a objetos', 'Modela um sistema pequeno de biblioteca ou estoque com regras explícitas e testes.', 'Outra pessoa demonstra os fluxos principais, explica as responsabilidades dos objetos e verifica casos limite.', 110),
  ('py-comp-fin-01', 'python', 'py-fin-01', 'Definir requisitos observáveis', 'Converte uma necessidade em comportamentos e limites verificáveis.', 'Registra quem usa o sistema, quais ações executa e como se reconhece cada resultado.', 10),
  ('py-comp-fin-02', 'python', 'py-fin-02', 'Planejar uma entrega incremental', 'Divide o projeto em partes pequenas ordenadas por valor e risco.', 'Entrega primeiro um fluxo mínimo executável antes de acrescentar recursos secundários.', 20),
  ('py-comp-fin-03', 'python', 'py-fin-03', 'Separar responsabilidades do projeto', 'Organiza interface, regras de negócio e persistência em módulos compreensíveis.', 'Testa uma regra sem depender de entrada de terminal ou de dados reais.', 30),
  ('py-comp-fin-04', 'python', 'py-fin-04', 'Modelar transações financeiras', 'Define campos e validações para receitas, despesas, categorias, datas e valores.', 'Recusa estados inválidos e explica por que o modelo representa cada transação.', 40),
  ('py-comp-fin-05', 'python', 'py-fin-05', 'Persistir com consultas parametrizadas', 'Usa SQLite com tabelas, chaves e parâmetros nas consultas.', 'Insere e consulta registros com parâmetros em vez de concatenar valores SQL.', 50),
  ('py-comp-fin-06', 'python', 'py-fin-06', 'Consultar dados persistidos corretamente', 'Recupera e filtra registros e calcula saldos a partir das transações.', 'Confere os resultados com dados conhecidos e mantém uma regra única de cálculo.', 60),
  ('py-comp-fin-07', 'python', 'py-fin-07', 'Criar uma interface de terminal clara', 'Organiza comandos e mensagens para orientar quem utiliza o programa.', 'Demonstra um fluxo principal e explica como a interface reage a uma escolha inválida.', 70),
  ('py-comp-fin-08', 'python', 'py-fin-08', 'Recuperar-se de erros previsíveis', 'Valida entradas e trata falhas de persistência sem indicar sucesso falso.', 'Explica o problema e o próximo passo sem esconder defeitos inesperados.', 80),
  ('py-comp-fin-09', 'python', 'py-fin-09', 'Testar regras com dados isolados', 'Automatiza testes de cálculo, filtros e validação sem depender da base real.', 'Os testes usam dados temporários e verificam resultados e pelo menos um caso limite.', 90),
  ('py-comp-fin-10', 'python', 'py-fin-10', 'Publicar e apresentar uma aplicação', 'Prepara uma entrega documentada que outra pessoa consegue executar e avaliar.', 'Demonstra o fluxo principal, explica uma limitação e indica um próximo passo realista.', 100)
insert into public.atividade (id, trilha, topico_id, tipo, titulo, enunciado, configuracao, dificuldade, ordem, publicada) values
  ('py-quiz-int-01', 'python', 'py-int-01', 'quiz', 'Classe ou objeto?', 'Uma classe Livro descreve título e autor. O que é livro_favorito = Livro("Mar", "Lia")?', '{"multipla":false,"alternativas":[{"id":"a","texto":"Uma instância de Livro, com valores próprios para seus atributos."},{"id":"b","texto":"Uma nova definição de classe chamada Livro."},{"id":"c","texto":"Um módulo da biblioteca padrão."},{"id":"d","texto":"Um método que altera todas as classes."}]}'::jsonb, 'intermediario', 10, true),
  ('py-completar-int-01', 'python', 'py-int-01', 'completar', 'Declare uma classe', 'Complete a palavra-chave para começar a definição de uma classe chamada Livro.', '{"codigo":"___ Livro:\n    pass","lacunas":[{"id":"palavra","rotulo":"Palavra-chave que define uma classe"}]}'::jsonb, 'intermediario', 20, true),
  ('py-quiz-int-02', 'python', 'py-int-02', 'quiz', 'O papel de self', 'Dentro de um método de instância, o que self representa?', '{"multipla":false,"alternativas":[{"id":"a","texto":"O objeto que recebeu a chamada do método."},{"id":"b","texto":"A classe pai em qualquer situação."},{"id":"c","texto":"Uma palavra reservada que o Python insere sem parâmetro."},{"id":"d","texto":"Uma cópia automática do módulo inteiro."}]}'::jsonb, 'intermediario', 10, true),
  ('py-saida-int-02', 'python', 'py-int-02', 'saida', 'Atributos de instâncias diferentes', 'Cada objeto guarda seu próprio nome. Qual texto aparece?', '{"codigo":"class Caixa:\n    def __init__(self, nome):\n        self.nome = nome\n\na = Caixa(\"azul\")\nb = Caixa(\"verde\")\nprint(a.nome)","rotuloResposta":"Texto exibido"}'::jsonb, 'intermediario', 20, true),
  ('py-quiz-int-03', 'python', 'py-int-03', 'quiz', 'Preserve uma invariante', 'Uma conta não pode ficar com saldo negativo. Onde deve viver a verificação de saque?', '{"multipla":false,"alternativas":[{"id":"a","texto":"No método que altera o saldo, para que toda chamada preserve a regra."},{"id":"b","texto":"Somente em uma mensagem da interface, sem conferir o valor."},{"id":"c","texto":"Em cada lugar do programa que por acaso chama o saque, repetida manualmente."},{"id":"d","texto":"Em um comentário que substitui a validação."}]}'::jsonb, 'intermediario', 10, true),
  ('py-erro-int-03', 'python', 'py-int-03', 'erro', 'Encontre o caminho que quebra a regra', 'A classe Conta valida saldo apenas no menu. Um teste chama conta.saldo = -20 e cria um estado inválido. Qual é a causa?', '{"multipla":false,"alternativas":[{"id":"a","texto":"A regra está fora do objeto e pode ser contornada por outros caminhos de alteração."},{"id":"b","texto":"Classes não podem guardar números negativos em Python."},{"id":"c","texto":"Todo atributo precisa ser global."},{"id":"d","texto":"A solução é herdar de uma classe de menu."}]}'::jsonb, 'intermediario', 20, true),
  ('py-quiz-int-04', 'python', 'py-int-04', 'quiz', 'Escolha uma relação coerente', 'Uma Biblioteca mantém vários objetos Livro. Qual relação descreve melhor esse modelo?', '{"multipla":false,"alternativas":[{"id":"a","texto":"Composição: uma biblioteca tem livros e coordena seu conjunto."},{"id":"b","texto":"Herança: uma biblioteca é um tipo de livro."},{"id":"c","texto":"Herança: todo livro é uma biblioteca."},{"id":"d","texto":"Não é possível uma classe guardar outros objetos."}]}'::jsonb, 'intermediario', 10, true),
  ('py-completar-int-04', 'python', 'py-int-04', 'completar', 'Acesse o comportamento composto', 'A classe Biblioteca guarda os livros em self.livros. Complete para devolver a coleção mantida pela biblioteca.', '{"codigo":"class Biblioteca:\n    def listar(self):\n        return self.___","lacunas":[{"id":"atributo","rotulo":"Atributo que guarda os livros"}]}'::jsonb, 'intermediario', 20, true),
  ('py-quiz-int-05', 'python', 'py-int-05', 'quiz', 'Representação para depuração', 'Qual método especial fornece uma representação voltada a depuração e aparece, por exemplo, no console interativo?', '{"multipla":false,"alternativas":[{"id":"a","texto":"__repr__"},{"id":"b","texto":"__loop__"},{"id":"c","texto":"__input__"},{"id":"d","texto":"__start__"}]}'::jsonb, 'intermediario', 10, true),
  ('py-saida-int-05', 'python', 'py-int-05', 'saida', 'Personalize a impressão do objeto', 'Qual saída é produzida quando print é chamado com um objeto que implementa __str__?', '{"codigo":"class Produto:\n    def __init__(self, nome):\n        self.nome = nome\n    def __str__(self):\n        return f\"Produto: {self.nome}\"\n\nprint(Produto(\"Caderno\"))","rotuloResposta":"Texto exibido"}'::jsonb, 'intermediario', 20, true),
  ('py-quiz-int-06', 'python', 'py-int-06', 'quiz', 'Quando a compreensão ajuda?', 'Você quer criar uma nova lista com o quadrado dos números pares. Quando list comprehension é uma boa escolha?', '{"multipla":false,"alternativas":[{"id":"a","texto":"Quando transformação e filtro cabem em uma expressão curta e legível."},{"id":"b","texto":"Sempre, mesmo com muitas condições aninhadas e efeitos colaterais."},{"id":"c","texto":"Somente quando a lista original está vazia."},{"id":"d","texto":"Para alterar a lista original enquanto ela é percorrida."}]}'::jsonb, 'intermediario', 10, true),
  ('py-completar-int-06', 'python', 'py-int-06', 'completar', 'Filtre e transforme', 'Complete a expressão para criar uma lista com o quadrado dos valores pares.', '{"codigo":"numeros = [1, 2, 3, 4]\nquadrados = [___ for n in numeros if n % 2 == 0]\nprint(quadrados)","lacunas":[{"id":"expressao","rotulo":"Expressão que calcula o quadrado do número atual"}]}'::jsonb, 'intermediario', 20, true),
  ('py-quiz-int-07', 'python', 'py-int-07', 'quiz', 'Produza sem guardar tudo', 'Uma sequência potencialmente grande deve entregar itens um por vez. Qual recurso permite escrever essa produção sob demanda?', '{"multipla":false,"alternativas":[{"id":"a","texto":"Uma função generator que usa yield."},{"id":"b","texto":"Uma lista global que guarda todos os resultados para sempre."},{"id":"c","texto":"Uma tupla que cresce automaticamente."},{"id":"d","texto":"Uma string que representa todo o arquivo."}]}'::jsonb, 'intermediario', 10, true),
  ('py-saida-int-07', 'python', 'py-int-07', 'saida', 'Consuma os valores do generator', 'O generator produz os números pares menores que limite. Informe a lista impressa.', '{"codigo":"def pares(limite):\n    for numero in range(limite):\n        if numero % 2 == 0:\n            yield numero\n\nprint(list(pares(5)))","rotuloResposta":"Lista exibida"}'::jsonb, 'intermediario', 20, true),
  ('py-quiz-int-08', 'python', 'py-int-08', 'quiz', 'Uma anotação não é validação', 'Uma função recebe valor: int. O que essa anotação garante por si só em tempo de execução?', '{"multipla":false,"alternativas":[{"id":"a","texto":"Ela comunica a intenção, mas Python não rejeita automaticamente todo valor de outro tipo."},{"id":"b","texto":"Ela converte qualquer entrada para inteiro automaticamente."},{"id":"c","texto":"Ela impede que a função seja chamada."},{"id":"d","texto":"Ela cria uma tabela no banco de dados."}]}'::jsonb, 'intermediario', 10, true),
  ('py-completar-int-08', 'python', 'py-int-08', 'completar', 'Declare dados com dataclass', 'Complete o decorador que gera métodos comuns para uma classe de dados.', '{"codigo":"from dataclasses import dataclass\n\n___\nclass Produto:\n    nome: str\n    preco: float","lacunas":[{"id":"decorador","rotulo":"Decorador que marca uma classe de dados"}]}'::jsonb, 'intermediario', 20, true),
  ('py-quiz-int-09', 'python', 'py-int-09', 'quiz', 'Garanta a limpeza do recurso', 'Por que abrir um arquivo com with open(...) é recomendado?', '{"multipla":false,"alternativas":[{"id":"a","texto":"O contexto fecha o arquivo ao sair do bloco, inclusive se ocorrer uma exceção."},{"id":"b","texto":"O arquivo nunca é fechado e fica sempre disponível."},{"id":"c","texto":"with converte todo conteúdo para JSON."},{"id":"d","texto":"with ignora qualquer erro ocorrido no bloco."}]}'::jsonb, 'intermediario', 10, true),
  ('py-completar-int-09', 'python', 'py-int-09', 'completar', 'Confira um padrão textual', 'Complete a função que exige que todo o texto seja composto por exatamente quatro dígitos.', '{"codigo":"import re\nvalido = re.___(r\"\\d{4}\", codigo) is not None","lacunas":[{"id":"funcao","rotulo":"Função que exige correspondência do texto inteiro"}]}'::jsonb, 'intermediario', 20, true),
  ('py-quiz-int-10', 'python', 'py-int-10', 'quiz', 'Entenda o custo de procurar', 'Em uma lista sem ordenação, qual estratégia no pior caso verifica cada item até encontrar o alvo?', '{"multipla":false,"alternativas":[{"id":"a","texto":"Busca linear, com trabalho proporcional à quantidade de itens."},{"id":"b","texto":"Busca binária, mesmo sem a lista estar ordenada."},{"id":"c","texto":"Acesso por índice de dicionário em tempo sempre proporcional a zero."},{"id":"d","texto":"Uma ordenação automática feita por input()."}]}'::jsonb, 'intermediario', 10, true),
  ('py-desafio-int-10', 'python', 'py-int-10', 'desafio', 'Encontre o primeiro índice', 'Leia N, depois uma linha com N inteiros e, por fim, um alvo. Percorra a lista da esquerda para a direita e imprima o índice da primeira ocorrência do alvo ou -1 se ele não existir.', '{"codigoInicial":"quantidade = int(input())\nnumeros = list(map(int, input().split()))\nalvo = int(input())\nindice = -1\n\n# Procure a primeira ocorrência e pare quando encontrá-la.\n\nprint(indice)","entradaExemplo":"5\n4 8 2 8 1\n8\n","saidaExemplo":"1\n","linguagem":"python","limiteCaracteres":12000}'::jsonb, 'intermediario', 20, true),
  ('py-projeto-biblioteca', 'python', 'py-int-10', 'projeto', 'Projeto — biblioteca ou controle de estoque', 'Escolha uma biblioteca ou um estoque e desenvolva uma aplicação orientada a objetos com regras claras, fluxos demonstráveis e testes automatizados.', '{"objetivo":"Consolidar classes, composição, encapsulamento, métodos, organização de módulos e testes em uma aplicação de escopo pequeno.","requisitos":[{"id":"modelo","titulo":"Modelar entidades","descricao":"Definir pelo menos duas entidades com estado e responsabilidades justificadas, como Livro e Biblioteca ou Produto e Estoque."},{"id":"regras","titulo":"Aplicar regras do domínio","descricao":"Implementar ao menos uma regra protegida, como impedir empréstimo de item indisponível ou quantidade abaixo de zero."},{"id":"composicao","titulo":"Usar composição com propósito","descricao":"Uma entidade coordena ou contém outras sem herança artificial; explicar a escolha no resumo."},{"id":"fluxos","titulo":"Demonstrar operações","descricao":"Permitir cadastrar e consultar itens e executar uma operação principal do domínio, como emprestar/devolver ou movimentar estoque."},{"id":"testes","titulo":"Testar casos comuns e limites","descricao":"Adicionar testes automatizados para operações válidas, estado indisponível e pelo menos uma entrada inválida."},{"id":"organizacao","titulo":"Organizar e documentar","descricao":"Separar responsabilidades em funções ou módulos e incluir instruções claras para executar e testar."}],"criterios":[{"id":"corretude","titulo":"Regras corretas","descricao":"Os fluxos demonstrados respeitam a disponibilidade e as demais regras declaradas."},{"id":"modelo","titulo":"Modelo compreensível","descricao":"Classes têm responsabilidades justificadas e não são usadas apenas para substituir dicionários sem necessidade."},{"id":"testes","titulo":"Evidência automatizada","descricao":"Os testes cobrem resultados, erros previstos e ao menos um caso limite."},{"id":"compreensao","titulo":"Explicação do estudante","descricao":"O resumo descreve a escolha biblioteca ou estoque, uma relação entre objetos e o que foi aprendido."}],"entregaveis":["Link público do repositório ou arquivo .zip de até 20 MB","Resumo de pelo menos 20 caracteres explicando modelo e testes","Autoavaliação honesta dos requisitos concluídos"],"instrucoes":"Escolha biblioteca ou estoque. Envie um repositório público ou um arquivo .zip de até 20 MB; não inclua ambientes virtuais nem dados pessoais. Explique no resumo suas classes, a regra principal e como executou os testes. Marque apenas o que verificou; a equipe revisará e dará feedback.","limiteResumo":2000,"plataformas":["github.com","gitlab.com","bitbucket.org"]}'::jsonb, 'intermediario', 30, true),
  ('py-quiz-fin-01', 'python', 'py-fin-01', 'quiz', 'Transforme uma ideia em requisito', 'Qual requisito pode ser verificado sem depender de uma interpretação subjetiva?', '{"multipla":false,"alternativas":[{"id":"a","texto":"Ao cadastrar uma despesa de 25,00, o sistema persiste a categoria e mostra o lançamento na consulta."},{"id":"b","texto":"O programa é bonito e fácil."},{"id":"c","texto":"A aplicação faz tudo que uma pessoa precisa."},{"id":"d","texto":"O código é profissional."}]}'::jsonb, 'intermediario', 10, true),
  ('py-completar-fin-01', 'python', 'py-fin-01', 'completar', 'Defina critérios de aceitação', 'Complete o formato comum para descrever um cenário verificável: Dado..., Quando..., ___.', '{"codigo":"Dado um saldo conhecido, quando uma despesa é cadastrada, ___ o novo saldo é recalculado.","lacunas":[{"id":"resultado","rotulo":"Palavra que introduz o resultado esperado"}]}'::jsonb, 'intermediario', 20, true),
  ('py-quiz-fin-02', 'python', 'py-fin-02', 'quiz', 'Entregue uma primeira fatia útil', 'Qual plano reduz o risco de construir o sistema inteiro sem verificar a persistência?', '{"multipla":false,"alternativas":[{"id":"a","texto":"Começar por cadastrar uma transação, salvá-la e recuperá-la antes de adicionar filtros e relatórios."},{"id":"b","texto":"Escrever todas as telas e só testar no último dia."},{"id":"c","texto":"Implementar primeiro recursos opcionais sem definir o fluxo básico."},{"id":"d","texto":"Esperar até conhecer todos os detalhes futuros antes de executar qualquer código."}]}'::jsonb, 'intermediario', 10, true),
  ('py-completar-fin-02', 'python', 'py-fin-02', 'completar', 'Ordene a primeira entrega', 'Antes de construir filtros e relatórios, complete a sequência mínima: modelar uma transação, ___, conferir o saldo.', '{"codigo":"modelar → ___ → conferir o saldo","lacunas":[{"id":"passo","rotulo":"Ação que torna os dados disponíveis após reiniciar"}]}'::jsonb, 'intermediario', 20, true),
  ('py-quiz-fin-03', 'python', 'py-fin-03', 'quiz', 'Separe a interface da regra', 'Qual divisão facilita testar o cálculo de saldo sem simular respostas no terminal?', '{"multipla":false,"alternativas":[{"id":"a","texto":"Deixar a regra de cálculo em uma função ou módulo independente da interface."},{"id":"b","texto":"Calcular o saldo diretamente dentro de cada print do menu."},{"id":"c","texto":"Duplicar o mesmo cálculo em todos os comandos."},{"id":"d","texto":"Fazer a regra depender de input em toda chamada."}]}'::jsonb, 'intermediario', 10, true),
  ('py-completar-fin-03', 'python', 'py-fin-03', 'completar', 'Proteja o ponto de entrada', 'Complete a condição que executa o menu apenas quando o arquivo for chamado como programa principal.', '{"codigo":"if __name__ == \"___\":\n    iniciar_menu()","lacunas":[{"id":"valor","rotulo":"Valor especial do módulo executado diretamente"}]}'::jsonb, 'intermediario', 20, true),
  ('py-quiz-fin-04', 'python', 'py-fin-04', 'quiz', 'Modele um valor financeiro válido', 'Uma despesa deve armazenar um valor positivo e seu tipo indica que será subtraído do saldo. Qual desenho evita duas representações confusas para o mesmo conceito?', '{"multipla":false,"alternativas":[{"id":"a","texto":"Guardar valor positivo e tipo receita ou despesa, aplicando o sinal na regra de cálculo."},{"id":"b","texto":"Guardar valor negativo para despesas e também inverter o sinal de novo no cálculo."},{"id":"c","texto":"Guardar o valor em texto sem validação."},{"id":"d","texto":"Omitir tipo e deduzir a categoria pela descrição livre."}]}'::jsonb, 'intermediario', 10, true),
  ('py-completar-fin-04', 'python', 'py-fin-04', 'completar', 'Valide um campo obrigatório', 'Complete para rejeitar uma transação cujo tipo não seja um dos dois valores aceitos.', '{"codigo":"if transacao.tipo not in (\"receita\", \"despesa\"):\n    raise ___(\"Tipo inválido\")","lacunas":[{"id":"excecao","rotulo":"Exceção adequada para um valor fora das regras"}]}'::jsonb, 'intermediario', 20, true),
  ('py-quiz-fin-05', 'python', 'py-fin-05', 'quiz', 'Evite montar SQL com valores', 'Qual padrão usa um parâmetro para filtrar transações por categoria?', '{"multipla":false,"alternativas":[{"id":"a","texto":"cursor.execute(\"SELECT * FROM transacao WHERE categoria = ?\", (categoria,))"},{"id":"b","texto":"cursor.execute(\"SELECT * FROM transacao WHERE categoria = \" + categoria)"},{"id":"c","texto":"cursor.execute(categoria)"},{"id":"d","texto":"cursor.execute(\"SELECT \" + categoria + \" FROM transacao\")"}]}'::jsonb, 'intermediario', 10, true),
  ('py-completar-fin-05', 'python', 'py-fin-05', 'completar', 'Use placeholder parametrizado', 'Complete o placeholder para uma consulta SQLite que filtra pela categoria.', '{"codigo":"cursor.execute(\"SELECT valor FROM transacao WHERE categoria = ___\", (categoria,))","lacunas":[{"id":"placeholder","rotulo":"Placeholder de valor do SQLite"}]}'::jsonb, 'intermediario', 20, true),
  ('py-quiz-fin-06', 'python', 'py-fin-06', 'quiz', 'Calcule a partir dos registros', 'Por que o saldo deve ser calculado a partir das transações persistidas em vez de manter apenas um total separado?', '{"multipla":false,"alternativas":[{"id":"a","texto":"Porque um total armazenado à parte pode ficar divergente quando uma transação falha ou muda."},{"id":"b","texto":"Porque SQLite não permite armazenar números."},{"id":"c","texto":"Porque consultas não podem somar valores."},{"id":"d","texto":"Porque o saldo deve ser definido uma única vez e nunca atualizado."}]}'::jsonb, 'intermediario', 10, true),
  ('py-saida-fin-06', 'python', 'py-fin-06', 'saida', 'Confira totais conhecidos', 'O exemplo lista valores de receitas e despesas. Qual saldo será exibido?', '{"codigo":"receitas = [100, 50]\ndespesas = [30, 20]\nsaldo = sum(receitas) - sum(despesas)\nprint(saldo)","rotuloResposta":"Saldo numérico"}'::jsonb, 'intermediario', 20, true),
  ('py-quiz-fin-07', 'python', 'py-fin-07', 'quiz', 'Uma interface de terminal previsível', 'Ao mostrar um menu, qual comportamento ajuda quem usa a aplicação?', '{"multipla":false,"alternativas":[{"id":"a","texto":"Informar opções válidas, confirmar o que foi concluído e explicar como corrigir uma escolha inválida."},{"id":"b","texto":"Encerrar sem mensagem quando a opção digitada não existe."},{"id":"c","texto":"Misturar leitura do terminal com cada regra de negócio."},{"id":"d","texto":"Mostrar uma exceção técnica para qualquer entrada inesperada."}]}'::jsonb, 'intermediario', 10, true),
  ('py-completar-fin-07', 'python', 'py-fin-07', 'completar', 'Repita o menu até sair', 'Complete a estrutura que repete um menu enquanto a pessoa ainda não escolheu sair.', '{"codigo":"opcao = \"\"\n___ opcao != \"sair\":\n    opcao = input(\"Opção: \")","lacunas":[{"id":"laço","rotulo":"Laço adequado quando o fim depende da escolha"}]}'::jsonb, 'intermediario', 20, true),
  ('py-quiz-fin-08', 'python', 'py-fin-08', 'quiz', 'Não esconda falhas do banco', 'Uma gravação SQLite falhou por causa de uma restrição. Qual resposta é mais confiável para a pessoa usuária?', '{"multipla":false,"alternativas":[{"id":"a","texto":"Informar que não foi possível salvar, explicar a regra relevante e não confirmar sucesso."},{"id":"b","texto":"Ignorar a exceção e exibir \"Salvo\"."},{"id":"c","texto":"Apagar todos os registros e continuar."},{"id":"d","texto":"Capturar qualquer erro e retornar uma lista vazia como se não houvesse dados."}]}'::jsonb, 'intermediario', 10, true),
  ('py-completar-fin-08', 'python', 'py-fin-08', 'completar', 'Trate uma restrição violada', 'Complete a exceção específica do sqlite3 para conflito com uma restrição de integridade.', '{"codigo":"try:\n    salvar_transacao()\nexcept sqlite3.___:\n    print(\"Revise os campos da transação.\")","lacunas":[{"id":"excecao","rotulo":"Exceção de violação de integridade"}]}'::jsonb, 'intermediario', 20, true),
  ('py-quiz-fin-09', 'python', 'py-fin-09', 'quiz', 'Isole os dados dos testes', 'Por que usar um banco SQLite temporário nos testes?', '{"multipla":false,"alternativas":[{"id":"a","texto":"Para manter os testes isolados e evitar misturar ou apagar dados reais do projeto."},{"id":"b","texto":"Para impedir que os testes consultem qualquer tabela."},{"id":"c","texto":"Porque testes não podem executar SQL."},{"id":"d","texto":"Para fazer os testes dependerem do banco pessoal de quem desenvolve."}]}'::jsonb, 'intermediario', 10, true),
  ('py-completar-fin-09', 'python', 'py-fin-09', 'completar', 'Verifique um resultado no pytest', 'Complete a asserção que confere se a função calcular_saldo devolve 70 para os dados preparados.', '{"codigo":"def test_calcular_saldo():\n    assert calcular_saldo(dados) ___ 70","lacunas":[{"id":"comparacao","rotulo":"Operador que compara o resultado esperado"}]}'::jsonb, 'intermediario', 20, true),
  ('py-quiz-fin-10', 'python', 'py-fin-10', 'quiz', 'Apresente também os limites', 'Além de demonstrar que o sistema funciona, o que torna uma apresentação técnica mais confiável?', '{"multipla":false,"alternativas":[{"id":"a","texto":"Explicar uma limitação conhecida e um próximo passo coerente."},{"id":"b","texto":"Omitir falhas conhecidas para parecer completo."},{"id":"c","texto":"Prometer recursos que não foram implementados."},{"id":"d","texto":"Mostrar apenas o código sem explicar como executar."}]}'::jsonb, 'intermediario', 10, true),
  ('py-completar-fin-10', 'python', 'py-fin-10', 'completar', 'Documente as instruções', 'Um README de entrega deve explicar como instalar, executar e ___.', '{"codigo":"Instalação → execução → ___","lacunas":[{"id":"secao","rotulo":"Passo para verificar automaticamente as regras do projeto"}]}'::jsonb, 'intermediario', 20, true)
insert into public.atividade_gabarito (atividade_id, configuracao) values
  ('py-quiz-int-01', '{"corretas":["a"],"explicacao":"Livro é a classe; livro_favorito é uma instância criada a partir dela e recebe seus próprios valores."}'::jsonb),
  ('py-completar-int-01', '{"lacunas":{"palavra":["class"]},"explicacao":"class inicia uma definição de classe. O corpo é indentado e pode começar com pass enquanto ainda está vazio."}'::jsonb),
  ('py-quiz-int-02', '{"corretas":["a"],"explicacao":"Em um método de instância, Python passa o objeto como primeiro argumento; por convenção esse parâmetro se chama self."}'::jsonb),
  ('py-saida-int-02', '{"aceitas":["azul"],"explicacao":"Cada chamada de Caixa cria uma instância com seu próprio atributo nome. a.nome continua sendo azul."}'::jsonb),
  ('py-quiz-int-03', '{"corretas":["a"],"explicacao":"A regra precisa ser protegida no ponto que altera o estado, para continuar válida mesmo quando outra parte do programa usa o objeto."}'::jsonb),
  ('py-erro-int-03', '{"corretas":["a"],"explicacao":"Validar apenas no menu deixa outros caminhos livres para criar saldo inválido. Encapsule a alteração em uma operação que preserve a invariante."}'::jsonb),
  ('py-quiz-int-04', '{"corretas":["a"],"explicacao":"Biblioteca tem livros; um livro não é um tipo de biblioteca. A biblioteca pode coordenar os objetos Livro por composição."}'::jsonb),
  ('py-completar-int-04', '{"lacunas":{"atributo":["livros"]},"explicacao":"self.livros guarda a coleção composta pela biblioteca; o método pode devolvê-la para consulta."}'::jsonb),
  ('py-quiz-int-05', '{"corretas":["a"],"explicacao":"__repr__ é a representação voltada a depuração e ao console. __str__ é a forma mais amigável para apresentação a uma pessoa."}'::jsonb),
  ('py-saida-int-05', '{"aceitas":["Produto: Caderno"],"explicacao":"print chama str no objeto; como a classe define __str__, a mensagem retorna Produto: Caderno."}'::jsonb),
  ('py-quiz-int-06', '{"corretas":["a"],"explicacao":"Uma compreensão é útil quando transformação e filtro são curtos. Se a expressão exigir muitas etapas, um laço explícito costuma ser mais legível."}'::jsonb),
  ('py-completar-int-06', '{"lacunas":{"expressao":["n ** 2"]},"explicacao":"A compreensão percorre numeros, mantém apenas pares e produz o quadrado de cada um: [4, 16]."}'::jsonb),
  ('py-quiz-int-07', '{"corretas":["a"],"explicacao":"Uma função com yield produz um generator, que entrega valores à medida que é consumido, sem montar a coleção completa antes."}'::jsonb),
  ('py-saida-int-07', '{"aceitas":["[0, 2, 4]"],"explicacao":"range(5) visita 0 a 4. yield entrega os pares 0, 2 e 4; list consome o generator e reúne os valores para exibição."}'::jsonb),
  ('py-quiz-int-08', '{"corretas":["a"],"explicacao":"Type hints documentam e permitem análise por ferramentas, mas não fazem validação automática durante a execução normal."}'::jsonb),
  ('py-completar-int-08', '{"lacunas":{"decorador":["@dataclass"]},"explicacao":"@dataclass gera métodos comuns para uma classe cujo foco é carregar dados, a partir dos campos anotados."}'::jsonb),
  ('py-quiz-int-09', '{"corretas":["a"],"explicacao":"O gerenciador de contexto chama a rotina de limpeza ao sair do bloco, inclusive quando uma exceção interrompe as instruções."}'::jsonb),
  ('py-completar-int-09', '{"lacunas":{"funcao":["fullmatch"]},"explicacao":"re.fullmatch exige que o padrão corresponda ao texto inteiro. Para quatro dígitos, use uma expressão como r\"\\d{4}\"."}'::jsonb),
  ('py-quiz-int-10', '{"corretas":["a"],"explicacao":"Na busca linear, no pior caso verificamos todos os elementos. Busca binária exige dados ordenados e reduz o intervalo pela metade a cada comparação."}'::jsonb),
  ('py-desafio-int-10', '{"testes":[{"entrada":"5\n4 8 2 8 1\n8\n","saida":"1\n"},{"entrada":"4\n3 5 7 9\n3\n","saida":"0\n"},{"entrada":"3\n2 4 6\n5\n","saida":"-1\n"},{"entrada":"5\n1 1 1 1 1\n1\n","saida":"0\n"}],"explicacao":"Percorra os itens na ordem e guarde o primeiro índice que corresponde ao alvo. Interrompa a busca nesse momento; se terminar sem encontrar, mantenha -1."}'::jsonb),
  ('py-quiz-fin-01', '{"corretas":["a"],"explicacao":"O cenário declara uma entrada e um resultado que podem ser demonstrados. Adjetivos como bonito ou profissional precisam ser convertidos em critérios observáveis."}'::jsonb),
  ('py-completar-fin-01', '{"lacunas":{"resultado":["então","entao"]},"explicacao":"Dado, Quando, Então descreve contexto, ação e resultado esperado de um critério de aceitação."}'::jsonb),
  ('py-quiz-fin-02', '{"corretas":["a"],"explicacao":"Uma fatia mínima que persiste e recupera dados testa cedo a decisão mais arriscada; os filtros podem ser adicionados depois."}'::jsonb),
  ('py-completar-fin-02', '{"lacunas":{"passo":["persistir","salvar"]},"explicacao":"Salvar e recuperar a primeira transação torna a fatia mínima útil e valida o caminho de persistência antes de aumentar o escopo."}'::jsonb),
  ('py-quiz-fin-03', '{"corretas":["a"],"explicacao":"Separar a regra permite testá-la com valores conhecidos sem depender de teclado, terminal ou camada de apresentação."}'::jsonb),
  ('py-completar-fin-03', '{"lacunas":{"valor":["__main__"]},"explicacao":"__name__ recebe __main__ quando o arquivo é executado diretamente; ao ser importado, recebe o nome do módulo."}'::jsonb),
  ('py-quiz-fin-04', '{"corretas":["a"],"explicacao":"Um valor positivo mais um tipo explícito evita inverter sinais em mais de um lugar. A regra de saldo aplica a operação conforme o tipo."}'::jsonb),
  ('py-completar-fin-04', '{"lacunas":{"excecao":["ValueError"]},"explicacao":"ValueError comunica que o tipo do valor é válido, mas o conteúdo não atende às regras aceitas pela aplicação."}'::jsonb),
  ('py-quiz-fin-05', '{"corretas":["a"],"explicacao":"O placeholder ? e a tupla de parâmetros deixam o driver separar o comando SQL dos valores recebidos."}'::jsonb),
  ('py-completar-fin-05', '{"lacunas":{"placeholder":["?"]},"explicacao":"SQLite usa ? como placeholder posicional. Passe o valor em uma sequência separada do texto SQL."}'::jsonb),
  ('py-quiz-fin-06', '{"corretas":["a"],"explicacao":"Se uma gravação falhar ou um lançamento mudar, um total duplicado pode ficar desatualizado. Calcular a partir das transações mantém uma fonte de verdade."}'::jsonb),
  ('py-saida-fin-06', '{"aceitas":["100"],"explicacao":"As receitas totalizam 150 e as despesas 50. O saldo é 150 menos 50, igual a 100."}'::jsonb),
  ('py-quiz-fin-07', '{"corretas":["a"],"explicacao":"Opções explícitas e mensagens honestas ajudam a pessoa a continuar. Regras de negócio devem ficar separadas da leitura do terminal."}'::jsonb),
  ('py-completar-fin-07', '{"lacunas":{"laço":["while"]},"explicacao":"while repete enquanto a condição for verdadeira. O corpo precisa atualizar opcao para que a pessoa consiga sair."}'::jsonb),
  ('py-quiz-fin-08', '{"corretas":["a"],"explicacao":"Uma falha de gravação não pode virar confirmação de sucesso. Informe o problema recuperável sem esconder erros inesperados."}'::jsonb),
  ('py-completar-fin-08', '{"lacunas":{"excecao":["IntegrityError"]},"explicacao":"sqlite3.IntegrityError indica violação de uma restrição de integridade, como uma chave duplicada ou campo obrigatório ausente."}'::jsonb),
  ('py-quiz-fin-09', '{"corretas":["a"],"explicacao":"Banco temporário deixa o teste previsível e isolado, evitando alterar dados de demonstração ou dados reais."}'::jsonb),
  ('py-completar-fin-09', '{"lacunas":{"comparacao":["=="]},"explicacao":"== compara o valor retornado com o resultado esperado. Se forem diferentes, pytest marca o teste como falha."}'::jsonb),
  ('py-quiz-fin-10', '{"corretas":["a"],"explicacao":"Reconhecer limitações concretas e sugerir um próximo passo demonstra compreensão do escopo e evita prometer recursos inexistentes."}'::jsonb),
  ('py-completar-fin-10', '{"lacunas":{"secao":["testes","rodar os testes","testar"]},"explicacao":"Documentar como rodar os testes permite que outra pessoa verifique as regras sem adivinhar comandos ou dependências."}'::jsonb)
